('famille','jean-dominique-1','{"prenom":"Jean-Dominique","nom":"de Lacroix","titre":"secrétaire du roi","lieu_naissance":"Bayonne (probable)","role":"Frère aîné de Jean de Lacroix ; négociant bayonnais enrichi par le commerce maritime.","bio":"Selon le site du domaine, il achète en 1715 la charge de secrétaire du roi et, sans enfant, lègue sa fortune à son frère Jean. Wikipédia date l''achat de 1718 et la mort du titulaire de 1731 : les sources ne concordent pas.","parents":[],"conjoints":[],"vivant":false,"incertain":true,"source":"https://www.armagnac-ravignan.com/le-chateau"}'::jsonb),
